// Mensagem enviada pelo usuário
const msg =
  $input.first().json.mensagem ||
  $input.first().json.msg ||
  $('Webhook MA').first().json.body.data.message.conversation ||
  "";

// Mensagem que o usuário respondeu
const reply =
  $('Campos Iniciais').first().json.msgReply ||
  $('Webhook MA').first().json.body.data.contextInfo?.quotedMessage?.conversation ||
  $('Webhook MA').first().json.body.data.contextInfo?.quotedMessage?.extendedTextMessage?.text ||
  "";

// Monta finalQuery sem NENHUM escape manual
let finalQuery;

if (reply) {
  finalQuery = `O usuário respondeu a mensagem: ${reply} dizendo: ${msg}`;
} else {
  finalQuery = msg;
}

return [
  {
    json: {
      ...$json,
      finalQuery: finalQuery.toString().replace(/"/g,"").replace(/\n/g, "")
    },
  },
];

let query = $('Edit Fields2').first().json.mensagem;

return {
  ...$json,
  // Substitui aspas, remove \r\n, \n, \r e então remove espaços em branco do início/fim
  finalQuery: query.toString()
    .replace(/"/g, "")
    .replace(/(\r\n|\n|\r)/gm, "") 
    .trim()
};

